CREATE TABLE assistant_conversations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, card_id UUID NULL REFERENCES virtual_cards(id) ON DELETE SET NULL, transaction_id UUID NULL REFERENCES transactions(id) ON DELETE SET NULL, title TEXT NOT NULL DEFAULT 'Money help', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now()); ALTER TABLE assistant_conversations ENABLE ROW LEVEL SECURITY;
CREATE TABLE assistant_messages (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id UUID NOT NULL REFERENCES assistant_conversations(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK (role IN ('user', 'assistant', 'system')), content TEXT NOT NULL CHECK (char_length(content) BETWEEN 1 AND 8000), created_at TIMESTAMPTZ NOT NULL DEFAULT now()); ALTER TABLE assistant_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY assistant_conversations_owner ON assistant_conversations FOR ALL TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
CREATE POLICY assistant_messages_owner ON assistant_messages FOR ALL TO authenticated USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);
GRANT SELECT, INSERT, UPDATE, DELETE ON assistant_conversations TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON assistant_messages TO authenticated;
